        f.setAccessible(true);
        return (OptionBuilder) f.get(null);
    }

    @Test
    void testWithValueSeparatorSetsValueSeparatorAndReturnsSingletonInstance() throws Exception {
        // capture prior state
        char before = getValueSeparator();
        OptionBuilder instance = getInstance();

        // call method under test
        OptionBuilder returned = OptionBuilder.withValueSeparator();

        // returned must be the same singleton instance
        assertSame(instance, returned, "withValueSeparator() should return the singleton INSTANCE");

        // valueSeparator must have been changed from its previous value
        char after = getValueSeparator();
        assertNotEquals(before, after, "valueSeparator should be changed by withValueSeparator()");

        // if a Char.EQUAL field exists in org.apache.commons.cli.Char, ensure it matches
        try {
            Class<?> charClass = Class.forName("org.apache.commons.cli.Char");
            Field equalField = charClass.getDeclaredField("EQUAL");
            equalField.setAccessible(true);
            char expected = equalField.getChar(null);
            assertEquals(expected, after, "valueSeparator should be set to Char.EQUAL");
        } catch (ClassNotFoundException | NoSuchFieldException ignored) {
            // If Char.EQUAL is unavailable in this environment, at least ensure a change occurred (already asserted)
        }
    }

    @Test
    void testWithValueSeparatorIsIdempotentAndKeepsValue() throws Exception {
        // reset by capturing current value
        char before = getValueSeparator();

        // first invocation
        OptionBuilder first = OptionBuilder.withValueSeparator();
        char afterFirst = getValueSeparator();

        // second invocation
        OptionBuilder second = OptionBuilder.withValueSeparator();
        char afterSecond = getValueSeparator();

        // both invocations should return the same singleton instance
        assertSame(first, second, "Multiple invocations should return the same singleton instance");
        assertSame(getInstance(), first, "Returned instance should be the singleton INSTANCE");

        // valueSeparator should remain stable after the first invocation
